using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageAllGeneratedTypesTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace MyNs
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            public enum Color { Red, Green }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)] public int A { get; set; }
                [Key(1)] public Color C { get; set; }
            }

            [MessagePackObject]
            public class StringKeyed
            {
                [Key("a")] public int A { get; set; }
                [Key("b")] public string B { get; set; }
            }

            [Union(0, typeof(UnionCase))]
            public interface IUnion { }

            [MessagePackObject]
            public class UnionCase : IUnion
            {
                [Key(0)] public int X { get; set; }
            }
        }
        """;

    [Fact]
    public async Task GeneratedResolverIsExcludedFromCodeCoverage()
    {
        var (output, generated) = await RunGeneratorAsync();
        Assert.NotEmpty(generated);
        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("MyNs.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasAttribute(resolver!), "The generated resolver is not decorated with ExcludeFromCodeCoverage.");
    }

    [Fact]
    public async Task AllGeneratedTypesAreExcludedFromCodeCoverage()
    {
        var (output, generated) = await RunGeneratorAsync();
        Assert.NotEmpty(generated);
        var errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).Select(d => d.ToString()).ToList();
        Assert.True(errors.Count == 0, "Generated code does not compile: " + string.Join("; ", errors));

        var undecorated = new List<string>();
        int count = 0;
        foreach (SyntaxTree tree in generated)
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (BaseTypeDeclarationSyntax decl in tree.GetRoot().DescendantNodes().OfType<BaseTypeDeclarationSyntax>())
            {
                INamedTypeSymbol? symbol = model.GetDeclaredSymbol(decl);
                if (symbol is null)
                {
                    continue;
                }

                count++;
                if (!IsCovered(symbol))
                {
                    undecorated.Add(symbol.ToDisplayString());
                }
            }
        }

        Assert.True(count > 0, "No generated types found.");
        Assert.True(undecorated.Count == 0, "Generated types without ExcludeFromCodeCoverage: " + string.Join(", ", undecorated.Distinct()));
    }

    private static bool HasAttribute(INamedTypeSymbol type)
        => type.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static bool IsCovered(INamedTypeSymbol symbol)
    {
        for (INamedTypeSymbol? t = symbol; t is not null; t = t.ContainingType)
        {
            if (HasAttribute(t))
            {
                return true;
            }
        }

        return false;
    }

    private static async Task<(Compilation Output, List<SyntaxTree> Generated)> RunGeneratorAsync()
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        SyntaxTree input = CSharpSyntaxTree.ParseText(Source, parseOptions);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = framework.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        Compilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { input },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);
        List<SyntaxTree> generated = output.SyntaxTrees.Where(t => !ReferenceEquals(t, input)).ToList();
        return (output, generated);
    }
}

